// Lit les metadonnees (EXIF) d'une photo envoyee en FICHIER sur Telegram
const fs = require('fs');
const cp = require('child_process');
const item = $input.first();
const bin = item.binary && (item.binary.data || Object.values(item.binary)[0]);
if (!bin) return [{ json: { resultat: "ERREUR : fichier introuvable sur Telegram." } }];
const buf = await this.helpers.getBinaryDataBuffer(0, item.binary.data ? 'data' : Object.keys(item.binary)[0]);
const chemin = ($env.ARCHI_BASE || '') + '/osint_photo_' + Date.now() + '.' + (bin.fileExtension || 'jpg');
fs.writeFileSync(chemin, buf);
const py = ($env.ARCHI_SERVEUR_PY || (($env.ARCHI_DEPOT || '') + '/serveur/venv/Scripts/python.exe'));
const script = `
import json, sys
from PIL import Image, ExifTags
r = {}
try:
    im = Image.open(sys.argv[1]); ex = im.getexif()
    T = ExifTags.TAGS
    for k, v in ex.items():
        n = T.get(k, k)
        if n in ("Make", "Model", "Software", "DateTime"): r[n] = str(v)
    sub = ex.get_ifd(0x8769)
    for k, v in sub.items():
        n = T.get(k, k)
        if n in ("DateTimeOriginal", "LensModel"): r[n] = str(v)
    g = ex.get_ifd(0x8825)
    def dec(x, ref):
        d = float(x[0]) + float(x[1]) / 60 + float(x[2]) / 3600
        return -d if ref in ("S", "W") else d
    if 2 in g and 4 in g:
        lat, lon = dec(g[2], g.get(1, "N")), dec(g[4], g.get(3, "E"))
        r["GPS"] = f"{lat:.2f}, {lon:.2f}"   # environ 1 km : la commune, jamais la maison
    r["Taille"] = f"{im.width} x {im.height}"
except Exception as e:
    r["erreur"] = str(e)[:150]
print(json.dumps(r, ensure_ascii=False))
`;
let r;
try { r = JSON.parse(cp.execFileSync(py, ['-c', script, chemin], { timeout: 30000, windowsHide: true }).toString('utf8').trim().split(/\r?\n/).pop()); }
catch (e) { r = { erreur: String(e.message || e).slice(0, 150) }; }
try { fs.unlinkSync(chemin); } catch (e) {}
// date en toutes lettres (evite les erreurs de lecture) et lieu reel (OpenStreetMap), pour ne rien deviner
const MOIS = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
for (const k of ['DateTimeOriginal', 'DateTime']) {
  const m = String(r[k] || '').match(/^(\d{4}):(\d{2}):(\d{2}) (\d{2}):(\d{2})/);
  if (m) r[k] = `${parseInt(m[3])} ${MOIS[parseInt(m[2]) - 1]} ${m[1]} à ${m[4]} h ${m[5]}`;
}
if (r.DateTime && r.DateTime === r.DateTimeOriginal) delete r.DateTime;
if (r.DateTimeOriginal) { r['Date de prise de vue'] = r.DateTimeOriginal; delete r.DateTimeOriginal; }
if (r.Model) { r['Appareil'] = ((r.Make || '') + ' ' + r.Model).trim(); delete r.Make; delete r.Model; }
if (r.GPS) {
  const [la, lo] = r.GPS.split(',').map(x => x.trim());
  try {
    const g = await this.helpers.httpRequest({ url: `https://nominatim.openstreetmap.org/reverse?format=json&lat=${la}&lon=${lo}&zoom=10&accept-language=fr`, json: true, timeout: 20000, headers: { 'User-Agent': 'Archi assistant personnel (usage prive)' } });
    const a = g.address || {};
    const commune = a.village || a.town || a.city || a.hamlet || a.municipality || '';
    r['Lieu (OpenStreetMap)'] = [commune, a.county, a.country].filter(Boolean).join(', ') || g.display_name || '?';
  } catch (e) { r['Lieu (OpenStreetMap)'] = 'introuvable (' + String(e.message).slice(0, 60) + ')'; }
}
const lignes = Object.entries(r).filter(([k]) => k !== 'erreur').map(([k, v]) => `- ${k} : ${v}`);
return [{ json: { resultat: lignes.length > 1
  ? 'MÉTADONNÉES DE LA PHOTO (faits, à recopier tels quels, sans rien changer) :\n' + lignes.join('\n') + (r.GPS ? '' : "\n(aucune position GPS enregistrée)")
  : "Aucune métadonnée exploitable. Si la photo a été envoyée comme PHOTO sur Telegram, elles ont été effacées : il faut l'envoyer comme FICHIER (trombone, puis Fichier)." + (r.erreur ? ' (' + r.erreur + ')' : '') } }];

// Archi - OSINT outils : sources publiques pour Hunter (une action par appel)
const h = this.helpers;
const fs = require('fs');
const cp = require('child_process');
const inp = $('Execute Workflow Trigger').first().json;
const action = String(inp.action || '').toLowerCase().trim();
const cible = String(inp.cible || '').trim();
const out = (t) => [{ json: { resultat: t } }];
const attendre = (ms) => new Promise(r => setTimeout(r, ms));
const get = async (url, json = true, essais = 2) => {
  for (let i = 0; i < essais; i++) {
    try { return await h.httpRequest({ url, json, timeout: 30000, headers: { 'User-Agent': 'Mozilla/5.0 (Archi OSINT)' } }); }
    catch (e) { if (i === essais - 1) throw e; await attendre(4000); }
  }
};
if (!cible && action !== 'crises') return out('ERREUR : cible vide.');

try {
  // ---------- registres d'entreprises (France + Suisse) ----------
  if (action === 'entreprise') {
    const L = [];
    try {
      const fr = await get('https://recherche-entreprises.api.gouv.fr/search?per_page=3&q=' + encodeURIComponent(cible));
      for (const e of (fr.results || [])) {
        const s = e.siege || {};
        const dir = (e.dirigeants || []).slice(0, 5).map(d => (d.nom ? (d.prenoms || '') + ' ' + d.nom : d.denomination || '?') + (d.qualite ? ' (' + d.qualite + ')' : '')).join(', ');
        L.push(`FRANCE — ${e.nom_complet} | SIREN ${e.siren} | créée le ${e.date_creation || '?'} | état : ${e.etat_administratif === 'A' ? 'active' : 'fermée'} | activité ${s.activite_principale || '?'} | siège : ${s.adresse || s.libelle_commune || '?'} | effectif : ${e.tranche_effectif_salarie || '?'} | dirigeants : ${dir || '?'} | source : https://annuaire-entreprises.data.gouv.fr/entreprise/${e.siren}`);
      }
    } catch (e) { L.push('France : registre injoignable (' + e.message + ')'); }
    try {
      const ch = await h.httpRequest({ method: 'POST', url: 'https://www.zefix.admin.ch/ZefixREST/api/v1/firm/search.json', body: { name: cible, languageKey: 'fr', maxEntries: 3 }, json: true, timeout: 30000 });
      for (const e of (ch.list || [])) L.push(`SUISSE — ${e.name} | ${e.uidFormatted} | siège : ${e.legalSeat} | statut : ${e.status === 'EXISTIEREND' ? 'active' : e.status} | source : https://www.zefix.ch/fr/search/entity/list/firm/${e.ehraid}`);
    } catch (e) { L.push('Suisse : registre Zefix injoignable (' + e.message + ')'); }
    return out(L.length ? 'REGISTRES OFFICIELS pour « ' + cible + ' » :\n' + L.join('\n') : 'Rien trouvé dans les registres français et suisse.');
  }

  // ---------- archives du web (Wayback Machine) ----------
  if (action === 'archive') {
    const dom = cible.replace(/^https?:\/\//, '').replace(/\/.*$/, '');
    const rows = await get('https://web.archive.org/cdx/search/cdx?output=json&fl=timestamp,original,statuscode&collapse=timestamp:6&limit=300&url=' + encodeURIComponent(dom), true, 3);
    const data = (rows || []).slice(1);
    if (!data.length) return out('Aucune archive de ' + dom + ' dans la Wayback Machine.');
    const annees = {};
    for (const [ts] of data) annees[ts.slice(0, 4)] = (annees[ts.slice(0, 4)] || 0) + 1;
    const f = data[0][0], l = data[data.length - 1][0];
    const lien = ts => `https://web.archive.org/web/${ts}/${dom}`;
    return out(`ARCHIVES de ${dom} (Wayback Machine) :\nPremière capture : ${f.slice(0, 4)}-${f.slice(4, 6)}-${f.slice(6, 8)} → ${lien(f)}\nDernière capture du relevé : ${l.slice(0, 4)}-${l.slice(4, 6)}-${l.slice(6, 8)} → ${lien(l)}\nCaptures par année (une par mois au plus) : ${Object.entries(annees).map(([a, n]) => a + ' : ' + n).join(', ')}\nUn site très récent qui se présente comme ancien = signal d'arnaque.`);
  }

  // ---------- sous-domaines (certificats, crt.sh) ----------
  if (action === 'sous_domaines') {
    const dom = cible.replace(/^https?:\/\//, '').replace(/\/.*$/, '').replace(/^www\./, '');
    const certs = await get('https://crt.sh/?output=json&q=' + encodeURIComponent('%.' + dom), true, 2);
    const vus = {};
    for (const c of certs || []) for (const n of String(c.name_value || '').split('\n')) {
      const x = n.trim().replace(/^\*\./, '').toLowerCase();
      if (x.endsWith(dom) && (!vus[x] || c.not_before < vus[x])) vus[x] = c.not_before;
    }
    const liste = Object.entries(vus).sort((a, b) => a[1] < b[1] ? -1 : 1);
    const suspect = liste.filter(([n]) => /login|secure|account|compte|verif|pay|bank|banque|update|support|wallet/.test(n));
    return out(`SOUS-DOMAINES de ${dom} (certificats publics, crt.sh) : ${liste.length} trouvés.\n` +
      liste.slice(0, 60).map(([n, d]) => `- ${n} (premier certificat : ${String(d).slice(0, 10)})`).join('\n') +
      (suspect.length ? `\nÀ surveiller (mots typiques d'hameçonnage) : ${suspect.map(s => s[0]).join(', ')}` : '') +
      `\nSource : https://crt.sh/?q=%25.${dom}`);
  }

  // ---------- pseudo sur des centaines de sites (Maigret) ----------
  if (action === 'pseudo') {
    const base = cible.replace(/^@/, '').replace(/[^A-Za-z0-9._-]/g, '').slice(0, 40);
    if (!base) return out('ERREUR : pseudo invalide.');
    // variantes : tel quel, sans separateurs (Stone_Raider -> StoneRaider), en minuscules
    const vv = [base, base.replace(/[._-]/g, '')];
    const variantes = vv.filter((v, i) => vv.findIndex(x => x.toLowerCase() === v.toLowerCase()) === i).slice(0, 2);
    const dossier = ($env.ARCHI_BASE || '') + '/osint_tmp_' + Date.now();
    fs.mkdirSync(dossier, { recursive: true });
    const py = ($env.ARCHI_SERVEUR_PY || (($env.ARCHI_DEPOT || '') + '/serveur/venv/Scripts/python.exe'));
    // lancement NON bloquant : n8n reste reactif pendant les 1 a 3 minutes de recherche
    await new Promise((resolve) => {
      const p = cp.spawn(py, ['-m', 'maigret', ...variantes.filter(v => !/^-/.test(String(v))), '--top-sites', '500', '--timeout', '20', '-n', '10', '--no-recursion',
        '--no-color', '--no-progressbar', '-J', 'simple', '--folderoutput', dossier],
        { windowsHide: true, stdio: 'ignore', env: Object.assign({}, require('process').env, { PYTHONIOENCODING: 'utf-8' }) });
      const minuterie = setTimeout(() => { try { p.kill(); } catch (e) {} resolve(); }, 240000);
      p.on('exit', () => { clearTimeout(minuterie); resolve(); });
      p.on('error', () => { clearTimeout(minuterie); resolve(); });
    });
    const lignes = [], vus = new Set();
    let bloques = 0;
    for (const v of variantes) {
      const f = dossier + '/report_' + v + '_simple.json';
      if (!fs.existsSync(f)) continue;
      const d = JSON.parse(fs.readFileSync(f, 'utf8'));
      for (const [site, x] of Object.entries(d)) {
        const st = (x.status || {});
        if (st.status === 'Claimed') {
          const url = x.url_user || st.url || '';
          if (!vus.has(url)) { vus.add(url); lignes.push(`- ${site} (${v}) : ${url}`); }
        } else if (st.status === 'Unknown') bloques++;
      }
    }
    try { fs.rmSync(dossier, { recursive: true, force: true }); } catch (e) {}
    return out(`PSEUDO « ${base} » (variantes testées : ${variantes.join(', ')}) : ${lignes.length} comptes trouvés sur 500 sites (Maigret).\n` +
      (bloques ? `${bloques} vérifications impossibles (site protégé contre les robots ou limite de requêtes) : l'absence d'un site ne prouve rien.\n` : '') +
      `ATTENTION : un même pseudo peut appartenir à des personnes différentes ; ne relie un compte à la cible que si le contenu le confirme.\n` + lignes.slice(0, 60).join('\n'));
  }

  // ---------- crises et conflits recents ----------
  if (action === 'crises') {
    const titres = async (url, n) => {
      const x = String(await get(url, false));
      return [...x.matchAll(/<item>[\s\S]*?<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>[\s\S]*?<link>([\s\S]*?)<\/link>/g)].filter(m => !/[\u0600-\u06FF\u0400-\u04FF]/.test(m[1])).slice(0, n).map(m => `- ${m[1].trim()} → ${m[2].trim()}`);
    };
    const L = [];
    try { L.push('INTERNATIONAL CRISIS GROUP (analyses de conflits) :', ...(await titres('https://www.crisisgroup.org/rss', 10))); } catch (e) { L.push('Crisis Group injoignable.'); }
    try { L.push('', 'RELIEFWEB (crises humanitaires) :', ...(await titres('https://reliefweb.int/disasters/rss.xml', 8))); } catch (e) { L.push('ReliefWeb injoignable.'); }
    return out(L.join('\n') + (cible ? `\n\nFiltre demandé par l’utilisateur : « ${cible} » (garde ce qui le concerne, complète avec recherche_web).` : ''));
  }

  return out('ERREUR : action inconnue « ' + action + ' » (entreprise, archive, sous_domaines, pseudo, crises).');
} catch (e) {
  return out('ERREUR : ' + String(e.message || e).slice(0, 200));
}
